Проблема в том, что вы используете неправильную матрицу поворота и не учитываете правильное преобразование координат для радара. Вот исправленная версия:

```cpp
void addPlayersToRadar(Player * player) {
    Vector3 myPos = GetPosition(myPlayer);
    Vector3 playerPos = player->position;

    // Вычисляем относительную позицию игрока
    Vector3 relativePos = playerPos - myPos;

    // Получаем поворот камеры (только по Y оси для радара)
    Quaternion cameraRotation = GetRotation(get_main());

    // Применяем обратный поворот камеры к относительной позиции
    // Это даст нам позицию относительно направления камеры
    Vector3 rotatedPos = Quaternion::Inverse(cameraRotation) * relativePos;

    // Вычисляем расстояние и ограничиваем его
    float distance = sqrt(rotatedPos.x * rotatedPos.x + rotatedPos.z * rotatedPos.z);
    float maxRadarDistance = 180.0f;

    if (distance > maxRadarDistance) {
        // Нормализуем и масштабируем до максимального расстояния радара
        rotatedPos.x = (rotatedPos.x / distance) * maxRadarDistance;
        rotatedPos.z = (rotatedPos.z / distance) * maxRadarDistance;
    }

    // Преобразуем в координаты радара
    // Обратите внимание: используем -rotatedPos.x для правильной ориентации
    Vector2 radarPos = {
        radar_center.x - rotatedPos.x,  // Инвертируем X для правильного отображения
        radar_center.y - rotatedPos.z   // Инвертируем Z (обычно это глубина)
    };

    bg->AddCircleFilled(radarPos, 5, ImColor(255, 0, 0, 255));
}
```

Альтернативный вариант, если нужно использовать только угол поворота по Y оси:

```cpp
void addPlayersToRadar(Player * player) {
    Vector3 myPos = GetPosition(myPlayer);
    Vector3 playerPos = player->position;

    // Относительная позиция
    Vector3 relativePos = playerPos - myPos;

    // Получаем угол поворота камеры по Y оси
    Vector3 cameraEuler = GetRotation(get_main()).ToEulerAngles();
    float yaw = cameraEuler.y;

    // Поворачиваем координаты на угол камеры
    float cos_yaw = cos(-yaw); // Отрицательный угол для обратного поворота
    float sin_yaw = sin(-yaw);

    float rotated_x = relativePos.x * cos_yaw - relativePos.z * sin_yaw;
    float rotated_z = relativePos.x * sin_yaw + relativePos.z * cos_yaw;

    // Ограничиваем расстояние
    float distance = sqrt(rotated_x * rotated_x + rotated_z * rotated_z);
    float maxRadarDistance = 180.0f;

    if (distance > maxRadarDistance) {
        rotated_x = (rotated_x / distance) * maxRadarDistance;
        rotated_z = (rotated_z / distance) * maxRadarDistance;
    }

    // Позиция на радаре
    Vector2 radarPos = {
        radar_center.x + rotated_x,
        radar_center.y + rotated_z
    };

    bg->AddCircleFilled(radarPos, 5, ImColor(255, 0, 0, 255));
}
```

Основные исправления:
1. **Правильное применение поворота камеры** - используется обратный поворот
2. **Корректное ограничение расстояния** - сначала вычисляется реальное расстояние, затем координаты масштабируются
3. **Правильная ориентация** - учтена инверсия осей для корректного отображения на радаре

